/**
 * Phase 25 — Cloud Privacy Boundary
 *
 * Formally enforces what leaves the user's device and what is strictly forbidden.
 * Guarantees zero cloud leakage of original images, file binaries, file paths,
 * thumbnails, directory handles, or raw content hashes.
 *
 * ────────────── PRIVACY BOUNDARY ──────────────
 * ALLOWED ACROSS BOUNDARY TO CLOUD:
 *   - imageId: UUID string
 *   - fingerprint: HMAC-SHA256 user-salted hash (cryptographically decoupled from raw content)
 *   - caption: Semantic text description generated by Local AI / Browser AI
 *   - keywords: Cleaned array of search keywords
 *   - status: 'available' | 'missing' | 'deleted'
 *   - captionModel: Model identifier (e.g. 'qwen3-vl-8b-instruct')
 *   - captionVersion: Integer version number
 *   - captionEngine: 'local' | 'browser'
 *
 * NEVER ALLOWED (STRICTLY BLOCKED & STRIPPED):
 *   - original image (File object, binary buffer, Uint8Array)
 *   - Blob (Blob object)
 *   - Base64 data (data:image/..., base64 strings)
 *   - thumbnail (binary or base64)
 *   - Blob URL (blob:http://...)
 *   - absolute path (C:\..., /Users/..., etc.)
 *   - relative path (e.g. photos/vacation/sunset.jpg)
 *   - directory handle (FileSystemHandle, FileSystemDirectoryHandle)
 *   - raw contentHash (raw SHA-256 hash of image file)
 *   - local filesystem metadata (fileName, size, lastModified, folderId, folderName)
 */

export const ALLOWED_CLOUD_FIELDS = Object.freeze(new Set([
    'imageId',
    'fingerprint',
    'caption',
    'keywords',
    'status',
    'captionModel',
    'captionVersion',
    'captionEngine'
]));

export const FORBIDDEN_FIELD_NAMES = Object.freeze(new Set([
    'file',
    'blob',
    'thumbnail',
    'base64',
    'data',
    'path',
    'relativePath',
    'absolutePath',
    'handle',
    'contentHash',
    'fileName',
    'folderId',
    'folderName',
    'size',
    'lastModified',
    'url',
    'blobUrl',
    'buffer',
    'arrayBuffer',
    'embedding' // Ephemeral vector; cloud embeds on server or client embeds text only
]));

// Maximum in-memory audit trail records
const MAX_AUDIT_LOG_ENTRIES = 200;
const privacyAuditTrail = [];

/**
 * Checks if a value is a binary object (File, Blob, ArrayBuffer, TypedArray).
 */
export function isBinaryOrBlob(value) {
    if (!value) return false;
    if (typeof Blob !== 'undefined' && value instanceof Blob) return true;
    if (typeof File !== 'undefined' && value instanceof File) return true;
    if (typeof ArrayBuffer !== 'undefined' && value instanceof ArrayBuffer) return true;
    if (typeof ArrayBuffer !== 'undefined' && ArrayBuffer.isView(value)) return true;
    return false;
}

/**
 * Checks if a value is a blob: URL.
 */
export function isBlobUrl(value) {
    return typeof value === 'string' && value.toLowerCase().startsWith('blob:');
}

/**
 * Checks if a string contains base64 image or large binary data.
 */
export function isBase64Data(value) {
    if (typeof value !== 'string') return false;
    if (value.startsWith('data:image/') || value.startsWith('data:application/')) return true;
    // Heuristic: continuous base64 string > 256 chars with no spaces
    if (value.length > 256 && /^[A-Za-z0-9+/=]{256,}$/.test(value)) return true;
    return false;
}

/**
 * Checks if a value appears to be a local filesystem path.
 */
export function isLocalPath(value) {
    if (typeof value !== 'string') return false;
    // Windows drive letter: C:\ or C:/
    if (/^[a-zA-Z]:[/\\]/.test(value)) return true;
    // Unix/Linux root path
    if (value.startsWith('/') && !value.startsWith('//')) return true;
    // Backslash path notation
    if (value.includes('\\')) return true;
    // Direct file extension match
    if (/\.(jpg|jpeg|png|webp|gif|avif|heic|tiff|bmp|svg)$/i.test(value)) return true;
    return false;
}

/**
 * Checks if a value is a FileSystemAccess API handle.
 */
export function isFileSystemHandle(value) {
    if (!value || typeof value !== 'object') return false;
    if (typeof value.queryPermission === 'function' || typeof value.getFile === 'function') return true;
    if (value.kind === 'file' || value.kind === 'directory') return true;
    return false;
}

/**
 * Performs deep security validation on an object intended for cloud transmission.
 * Returns an array of detected privacy violations (empty array if completely clean).
 *
 * @param {Object} payload
 * @param {Object} [originalRecord] - Optional original record to detect contentHash leakage
 * @returns {{ isValid: boolean, violations: string[] }}
 */
export function validateCloudPayload(payload, originalRecord = null) {
    const violations = [];

    if (!payload || typeof payload !== 'object') {
        return { isValid: false, violations: ['Payload must be an object'] };
    }

    // Rule 1: No unallowlisted properties allowed in payload
    for (const key of Object.keys(payload)) {
        if (!ALLOWED_CLOUD_FIELDS.has(key)) {
            violations.push(`Unallowed property '${key}' detected in cloud payload`);
        }
    }

    // Rule 2: Explicitly forbid forbidden property names
    for (const key of Object.keys(payload)) {
        if (FORBIDDEN_FIELD_NAMES.has(key)) {
            violations.push(`Forbidden property name '${key}' found in cloud payload`);
        }
    }

    // Rule 3: Inspect each allowed property value for binary/path/hash contamination
    for (const [key, value] of Object.entries(payload)) {
        if (isBinaryOrBlob(value)) {
            violations.push(`Binary/Blob object detected in property '${key}'`);
        }
        if (isBlobUrl(value)) {
            violations.push(`Blob URL detected in property '${key}'`);
        }
        if (isBase64Data(value)) {
            violations.push(`Base64 encoded data detected in property '${key}'`);
        }
        if (isFileSystemHandle(value)) {
            violations.push(`FileSystemHandle detected in property '${key}'`);
        }
        if (key !== 'caption' && isLocalPath(value)) {
            violations.push(`Local filesystem path detected in property '${key}'`);
        }
    }

    // Rule 4: Verify raw contentHash is NEVER transmitted as fingerprint
    if (originalRecord?.contentHash && payload.fingerprint) {
        if (payload.fingerprint.toLowerCase() === originalRecord.contentHash.toLowerCase()) {
            violations.push('Raw contentHash detected in fingerprint field! Must use user-salted HMAC fingerprint.');
        }
    }

    // Rule 5: Ensure imageId is valid
    if (!payload.imageId || typeof payload.imageId !== 'string' || payload.imageId.trim().length === 0) {
        violations.push('Missing or invalid imageId in cloud payload');
    }

    return {
        isValid: violations.length === 0,
        violations
    };
}

/**
 * Enforces the Cloud Privacy Boundary on a single image record.
 * Strips all local filesystem info, image binaries, blobs, and raw hashes.
 * Produces a strictly allowlisted, validated, and immutable payload.
 *
 * @param {Object} record - Raw local image record from IndexedDB
 * @param {Object} [options]
 * @param {boolean} [options.strict=true] - Throw error on boundary violation
 * @returns {Readonly<Object>} Sanitized, frozen cloud payload
 */
export function enforcePrivacyBoundary(record, { strict = true } = {}) {
    if (!record || typeof record !== 'object') {
        throw new Error('[PrivacyBoundary] Cannot enforce privacy boundary on null or invalid record');
    }

    // Extract ONLY the permitted semantic properties
    const sanitized = {
        imageId: String(record.imageId),
        fingerprint: record.fingerprint ? String(record.fingerprint) : null,
        caption: typeof record.caption === 'string' ? record.caption.trim() : '',
        keywords: Array.isArray(record.keywords)
            ? record.keywords
                .filter(k => typeof k === 'string' && k.trim().length > 0)
                .map(k => k.trim().toLowerCase().slice(0, 50))
            : [],
        status: ['available', 'missing', 'deleted'].includes(record.status)
            ? record.status
            : 'available',
        captionModel: record.captionModel ? String(record.captionModel).slice(0, 60) : null,
        captionVersion: typeof record.captionVersion === 'number'
            ? record.captionVersion
            : (typeof record.version === 'number' ? record.version : 1),
        captionEngine: ['local', 'browser'].includes(record.captionEngine)
            ? record.captionEngine
            : (['local', 'browser'].includes(record.engine) ? record.engine : 'local')
    };

    // Deep validation of sanitized object
    const validation = validateCloudPayload(sanitized, record);
    if (!validation.isValid) {
        const errorMsg = `[PrivacyBoundary] Boundary enforcement failed: ${validation.violations.join('; ')}`;
        console.error(errorMsg);
        if (strict) {
            throw new Error(errorMsg);
        }
    }

    // Append to audit trail
    logPrivacyBoundaryCrossing({
        action: 'SANITIZE_SINGLE',
        imageId: sanitized.imageId,
        allowedFields: Object.keys(sanitized),
        strippedFields: Object.keys(record).filter(k => !ALLOWED_CLOUD_FIELDS.has(k)),
        timestamp: Date.now()
    });

    // Freeze object to guarantee it cannot be tampered with prior to HTTP dispatch
    return Object.freeze(sanitized);
}

/**
 * Enforces the Cloud Privacy Boundary on an array of records for batch cloud synchronization.
 *
 * @param {Array<Object>} records - Array of raw IndexedDB records
 * @param {Object} [options]
 * @returns {{ payloads: Array<Readonly<Object>>, rejectedCount: number, auditSummary: Object }}
 */
export function enforceBatchPrivacyBoundary(records, { strict = false } = {}) {
    if (!Array.isArray(records)) {
        return { payloads: [], rejectedCount: 0, auditSummary: { total: 0, accepted: 0 } };
    }

    const payloads = [];
    let rejectedCount = 0;

    for (const record of records) {
        try {
            const sanitized = enforcePrivacyBoundary(record, { strict });
            payloads.push(sanitized);
        } catch (err) {
            console.warn(`[PrivacyBoundary] Rejected record ${record?.imageId || 'unknown'} from cloud export:`, err);
            rejectedCount++;
        }
    }

    logPrivacyBoundaryCrossing({
        action: 'SANITIZE_BATCH',
        total: records.length,
        accepted: payloads.length,
        rejected: rejectedCount,
        timestamp: Date.now()
    });

    return {
        payloads: Object.freeze(payloads),
        rejectedCount,
        auditSummary: {
            total: records.length,
            accepted: payloads.length,
            rejected: rejectedCount
        }
    };
}

/**
 * Creates a minimal cloud tombstone payload for deleted/purged images.
 * Guarantees zero local path or file name leakage during cloud cleanup.
 *
 * @param {Object} record - { imageId, fingerprint }
 * @returns {Readonly<Object>} Minimal tombstone: { imageId, fingerprint, status: 'deleted' }
 */
export function createCloudTombstone(record) {
    if (!record?.imageId) {
        throw new Error('[PrivacyBoundary] Cannot create tombstone without imageId');
    }

    const tombstone = {
        imageId: String(record.imageId),
        fingerprint: record.fingerprint ? String(record.fingerprint) : null,
        status: 'deleted'
    };

    logPrivacyBoundaryCrossing({
        action: 'CREATE_TOMBSTONE',
        imageId: tombstone.imageId,
        timestamp: Date.now()
    });

    return Object.freeze(tombstone);
}

/**
 * Appends an entry to the in-memory privacy audit trail.
 */
function logPrivacyBoundaryCrossing(entry) {
    privacyAuditTrail.push(entry);
    if (privacyAuditTrail.length > MAX_AUDIT_LOG_ENTRIES) {
        privacyAuditTrail.shift();
    }
}

/**
 * Returns the current privacy audit trail for telemetry and user inspection.
 *
 * @returns {Array<Object>}
 */
export function getPrivacyBoundaryAuditLog() {
    return [...privacyAuditTrail];
}
